import Dict from '@baifendian/adhere-util-dict';
import Intl from '@baifendian/adhere-util-intl';
/**
 * 表单配置字典
 * 提供表单验证规则和弹窗容器配置
 */
var FormConfig = {
    /**
     * 初始化静态表单配置
     * 设置表单验证规则和弹窗容器函数
     */
    initStatic: function () {
        /**
         * 数字输入验证规则
         * 验证范围：1-200
         */
        Dict.handlers.FormInputNumberRule = function () { return ({
            type: 'number',
            message: Intl.get('input_range_1_200'),
            min: 1,
            max: 200,
        }); };
        /**
         * 空白字符验证规则
         * 不允许输入空白字符
         */
        Dict.handlers.FormWhitespaceRule = function () { return ({
            message: Intl.get('input_no_spaces'),
            whitespace: true,
        }); };
        /**
         * 字符串输入验证规则
         * 验证范围：1-100字符
         */
        Dict.handlers.FormInputStringRule = function () { return ({
            type: 'string',
            message: Intl.get('input_limit_100_chars'),
            min: 1,
            max: 100,
        }); };
        /**
         * 表单弹窗容器配置
         * 返回父元素作为弹窗容器
         */
        Dict.handlers.FormPopupContainer = function () { return function (el) { return el.parentElement; }; };
    },
};
export default FormConfig;
